import re
from pathlib import Path

import pytesseract
from openpyxl import Workbook
from PIL import Image, ImageOps

IMG_DIR = Path("/app/workspace/dataset/img")
OUTPUT_FILE = Path("/app/workspace/stat_ocr.xlsx")

# Priority 1 is highest; priority 4 lowest. Longer phrases listed before
# shorter overlapping ones at the same priority (keeps selection stable).
KEYWORDS_BY_PRIORITY = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    [
        "AMOUNT DUE",
        "BALANCE DUE",
        "TOTAL DUE",
        "NETT TOTAL",
        "NET TOTAL",
        "TOTAL",
        "AMOUNT",
    ],
]

STRONG_EXCLUSIONS = ["SUBTOTAL", "SUB TOTAL"]
WEAK_EXCLUSIONS = ["TAX", "GST", "SST", "DISCOUNT", "CHANGE", "CASH TENDERED"]

# monetary value regex: allows comma or dot as decimal separator (OCR may misread),
# optional thousands separators
AMOUNT_REGEX = re.compile(
    r"(?:(?<![\d,.])\d{1,3}(?:,\d{3})+|(?<![\d,.])\d+)?[.,]\d{2}(?![\d.])"
)

MONTH_MAP = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "sept": 9, "oct": 10, "nov": 11, "dec": 12,
}

SUMMARY_CUTOFF = re.compile(r"\bGST\s*SUMMARY\b", re.IGNORECASE)


def normalize_line(line: str) -> str:
    s = re.sub(r"[^A-Za-z0-9\s]", " ", line).upper()
    s = re.sub(r"\s+", " ", s).strip()
    s = re.sub(r"\bAMT\b", "AMOUNT", s)
    return s


def extract_last_amount(line: str):
    matches = AMOUNT_REGEX.findall(line)
    if not matches:
        return None
    raw = matches[-1].replace(",", ".")
    # if multiple dots, keep only the last as decimal
    if raw.count(".") > 1:
        parts = raw.split(".")
        raw = "".join(parts[:-1]) + "." + parts[-1]
    if raw.startswith("."):
        raw = "0" + raw
    try:
        return float(raw)
    except ValueError:
        return None


def truncate_at_summary(lines):
    for i, line in enumerate(lines):
        if SUMMARY_CUTOFF.search(line):
            return lines[:i]
    return lines


def find_total(text: str):
    lines_all = [ln for ln in text.splitlines() if ln.strip()]
    lines = truncate_at_summary(lines_all)
    norms = [normalize_line(ln) for ln in lines]

    # Two-pass: strict exclusions first, then relaxed.
    for strict in (True, False):
        for priority_keywords in KEYWORDS_BY_PRIORITY:
            candidates = []
            for i, (orig, norm) in enumerate(zip(lines, norms)):
                if any(ex in norm for ex in STRONG_EXCLUSIONS):
                    continue
                if strict and any(ex in norm for ex in WEAK_EXCLUSIONS):
                    continue
                matched_kw = None
                for kw in priority_keywords:
                    if kw in norm:
                        matched_kw = kw
                        break
                if not matched_kw:
                    continue
                amt = extract_last_amount(orig)
                if amt is None and i + 1 < len(lines):
                    amt = extract_last_amount(lines[i + 1])
                if amt is not None:
                    candidates.append((i, amt))
            if candidates:
                return candidates[-1][1]
    return None


def parse_date(text: str):
    patterns = [
        r"\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{4})\b",
        r"\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{2})\b",
    ]
    for pat in patterns:
        for m in re.finditer(pat, text):
            d, mth, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
            if y < 100:
                y += 2000
            if 2000 <= y <= 2099 and 1 <= mth <= 12 and 1 <= d <= 31:
                return f"{y:04d}-{mth:02d}-{d:02d}"

    pat_mon = re.compile(
        r"\b(\d{1,2})[\s\-]+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)[a-z]*[\s\-]+(\d{2,4})\b",
        re.IGNORECASE,
    )
    for m in pat_mon.finditer(text):
        d = int(m.group(1))
        mth = MONTH_MAP[m.group(2).lower()[:3]]
        y = int(m.group(3))
        if y < 100:
            y += 2000
        if 2000 <= y <= 2099 and 1 <= d <= 31:
            return f"{y:04d}-{mth:02d}-{d:02d}"
    return None


def ocr_variants(path: Path):
    """Yield text output for several preprocessing variants."""
    base = Image.open(path).convert("RGB")
    w, h = base.size

    # Variant 1: resize to h ~ 2000, grayscale + autocontrast
    v1 = base.copy()
    if h > 2000:
        v1 = v1.resize((int(w * 2000 / h), 2000), Image.LANCZOS)
    elif h < 1200:
        v1 = v1.resize((int(w * 1500 / h), 1500), Image.LANCZOS)
    g1 = ImageOps.autocontrast(v1.convert("L"))
    yield pytesseract.image_to_string(g1, config="--psm 6")

    # Variant 2: downscale aggressively for very large images
    if h > 4000:
        v2 = base.resize((w // 4, h // 4), Image.LANCZOS)
        g2 = ImageOps.autocontrast(v2.convert("L"))
        yield pytesseract.image_to_string(g2, config="--psm 6")

    # Variant 3: red channel only (removes pink highlighting)
    r_channel = base.split()[0]
    v3 = r_channel
    if h > 2000:
        v3 = v3.resize((int(w * 2000 / h), 2000), Image.LANCZOS)
    g3 = ImageOps.autocontrast(v3)
    yield pytesseract.image_to_string(g3, config="--psm 6")


def extract(path: Path):
    date_iso = None
    total = None
    all_text = []
    for text in ocr_variants(path):
        all_text.append(text)
        if date_iso is None:
            date_iso = parse_date(text)
        if total is None:
            total = find_total(text)

    # one more attempt on concatenated text for robustness
    combined = "\n".join(all_text)
    if date_iso is None:
        date_iso = parse_date(combined)
    if total is None:
        total = find_total(combined)

    total_str = f"{total:.2f}" if total is not None else None
    return date_iso, total_str


def main():
    rows = []
    for fp in sorted(IMG_DIR.iterdir()):
        if fp.suffix.lower() not in {".jpg", ".jpeg", ".png"}:
            continue
        date_iso, total_str = extract(fp)
        rows.append((fp.name, date_iso, total_str))
        print(f"{fp.name}: date={date_iso}, total={total_str}")

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for r in rows:
        ws.append(r)
    wb.save(OUTPUT_FILE)
    print(f"\nSaved {OUTPUT_FILE}")


if __name__ == "__main__":
    main()
